import {quoteItem,quoteAmounts,quoteTotals,quoteMarkup,money} from './quote-domain.js';
export function setupQuote(){const $=id=>document.getElementById(id);let profile=null,owner=null,selected=null,quote={items:[],customer:'',notes:''};const key=()=> 'repoe-quote-v1:'+owner;
 function say(text){$('quote-message').textContent=text;}
 function save(){try{sessionStorage.setItem(key(),JSON.stringify(quote));}catch{say('Não foi possível salvar o orçamento nesta aba. Imprima antes de fechar.');}}
 function select(product){selected=product;let valid=false;try{if(product){const item=quoteItem(product,1);valid=true;$('quote-selection').textContent=item.name+' · '+money(item.price)+' / '+item.unit;}}catch(error){$('quote-selection').textContent=error.message;}if(!product)$('quote-selection').textContent='Consulte e selecione um produto acima.';$('quote-add').disabled=!valid||!profile?.active;}
 function total(){try{const sums=quoteTotals(quote.items);$('quote-total').textContent='Total: '+money(sums.total)+(sums.discount?' · Desconto: '+money(sums.discount):'');}catch(error){say(error.message);}}
 function render(){const root=$('quote-items');root.replaceChildren();for(const item of quote.items){const row=document.createElement('article');row.className='quote-item';const title=document.createElement('strong');title.textContent=item.name;const meta=document.createElement('p');meta.className='muted small';meta.textContent='Cód. '+item.code+' · '+money(item.price)+' / '+item.unit;const fields=document.createElement('div');fields.className='quote-item-fields';const line=document.createElement('strong');line.textContent=money(quoteAmounts(item).total);
 for(const [field,label,max,step] of [['quantity','Quantidade',99999,0.001],['discount','Desconto (%)',100,0.01]]){const wrap=document.createElement('label');wrap.textContent=label;const input=document.createElement('input');input.type='number';input.min=field==='quantity'?0.001:0;input.max=max;input.step=step;input.required=true;input.value=item[field];input.onchange=()=>{const next={...item,[field]:Number(input.value)};try{if(!input.reportValidity())throw new Error('Confira o valor informado.');quoteAmounts(next);item[field]=next[field];line.textContent=money(quoteAmounts(item).total);save();total();say('Orçamento salvo nesta aba.');}catch(error){input.value=item[field];say(error.message);}};wrap.append(input);fields.append(wrap);}
 const remove=document.createElement('button');remove.type='button';remove.className='ghost danger';remove.textContent='Excluir';remove.setAttribute('aria-label','Excluir '+item.name+' do orçamento');remove.onclick=()=>{quote.items=quote.items.filter(i=>i.id!==item.id);save();render();};fields.append(line,remove);row.append(title,meta,fields);root.append(row);}
 $('quote-print').disabled=$('quote-clear').disabled=!quote.items.length;total();}
 $('quote-add-form').onsubmit=e=>{e.preventDefault();if(!profile?.active||!selected)return;try{if(quote.items.length>=100)throw new Error('Limite de 100 itens por orçamento.');quote.items.push(quoteItem(selected,$('quote-quantity').value));save();render();$('quote-quantity').value='1';say('Produto adicionado. Ajuste o desconto por item, se necessário.');}catch(error){say(error.message);}};
 $('lookup-code').addEventListener('input',()=>select(null));
 for(const field of ['customer','notes'])$('quote-'+field).oninput=()=>{quote[field]=$('quote-'+field).value;save();};
 const confirm=document.createElement('dialog');confirm.className='confirm-dialog';confirm.innerHTML='<h2>Limpar orçamento?</h2><p>Os itens deste orçamento serão removidos desta aba.</p><div class="confirm-actions"><button type="button" class="secondary" data-cancel>Cancelar</button><button type="button" class="primary" data-confirm>Limpar</button></div>';document.body.append(confirm);confirm.querySelector('[data-cancel]').onclick=()=>confirm.close();confirm.querySelector('[data-confirm]').onclick=()=>{quote={items:[],customer:'',notes:''};$('quote-customer').value=$('quote-notes').value='';save();render();confirm.close();say('Orçamento limpo.');};$('quote-clear').onclick=()=>confirm.showModal();
 $('quote-print').onclick=async()=>{if(!quote.items.length||!profile?.active)return;const button=$('quote-print');button.disabled=true;let root;const title=document.title;const cleanup=()=>{root?.remove();document.title=title;window.removeEventListener('afterprint',cleanup);button.disabled=!quote.items.length;};try{document.getElementById('print-list')?.remove();root=document.createElement('section');root.id='print-list';root.innerHTML=quoteMarkup(quote,profile.name);document.body.append(root);document.title='Orçamento';window.addEventListener('afterprint',cleanup);await root.querySelector('img').decode();window.print();button.disabled=false;}catch(error){cleanup();say(error.message||'Não foi possível imprimir.');}};
 return {select,configure(next,id){profile=next;select(null);if(owner===id)return;owner=id;quote={items:[],customer:'',notes:''};if(owner)try{const saved=JSON.parse(sessionStorage.getItem(key())||'null');if(saved&&Array.isArray(saved.items)&&saved.items.length<=100){quoteTotals(saved.items);quote={items:saved.items,customer:String(saved.customer||'').slice(0,120),notes:String(saved.notes||'').slice(0,500)};}}catch{say('Não foi possível recuperar o orçamento anterior.');}$('quote-customer').value=quote.customer;$('quote-notes').value=quote.notes;render();}};
}
